import{_ as t,o as e,c as o,a5 as a}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"798读取excell某列内容搜索文件并移动到指定文件夹","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["搜索文件复制","搜索文件并移动或复制","搜索文件移动"]},"headers":[],"relativePath":"md/文件及文件夹批处理/798读取excell某列内容搜索文件并移动到指定文件夹.md","filePath":"md/文件及文件夹批处理/798读取excell某列内容搜索文件并移动到指定文件夹.md"}'),n={name:"md/文件及文件夹批处理/798读取excell某列内容搜索文件并移动到指定文件夹.md"};function s(l,r,p,i,b,c){return e(),o("div",null,[...r[0]||(r[0]=[a('<h3 id="读取excell某列内容搜索文件并移动到指定文件夹" tabindex="-1">读取excell某列内容搜索文件并移动到指定文件夹 <a class="header-anchor" href="#读取excell某列内容搜索文件并移动到指定文件夹" aria-label="Permalink to &quot;读取excell某列内容搜索文件并移动到指定文件夹&quot;">​</a></h3><p>读取xlsx文档，根据指定列搜索每个单元格内容，在指定文件文件夹下搜索与单元格内容相同的文件，移动文件到指定文件夹</p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有文件。</p><p>【操作方法】：只需要输入A文件夹路径即可，支持子文件夹自动穿透，选择xlsx（excell）文档，输入相关参数，输入目标文件夹路径即可。</p><p>程序运行后会将指定的xlsx中某列每个单元格内容与目标搜索文件夹下文件名相同的文件移动或复制到指定文件夹下。</p><p><strong>注：xlsx文档只支持工作表1，也就是打开excell文档后看到的默认界面。搜索列只能搜索一列，不能同时搜索多列。如果第一行是标题，则从第二行开始读取数据，如果第一行就是数据则从第一行开始读取数据。</strong></p><p>【1】、支持的文件格式：所有格式或自定义格式</p><p>【2】、是否支持子文件夹穿透：支持</p><h3 id="📑-文件结构树示意" tabindex="-1">📑 文件结构树示意 <a class="header-anchor" href="#📑-文件结构树示意" aria-label="Permalink to &quot;📑 文件结构树示意&quot;">​</a></h3><p>输入A文件夹，选择xlsx文档，自动搜索A文件夹下与xlsx（excell）文档指定列单元格内容相同文件复制或移动。</p><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p>注意：先测试备份原文件再批量使用</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250812200306175500018670237.png" alt=""></p><h3 id="📑-演示视频" tabindex="-1">📑 演示视频 <a class="header-anchor" href="#📑-演示视频" aria-label="Permalink to &quot;📑 演示视频&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1octdzTELk/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1octdzTELk/</a></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统</p><p>注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1973.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1973.html</a></p>',21)])])}const _=t(n,[["render",s]]);export{h as __pageData,_ as default};
